import random

from txn_simulator import Workload
from workloads import WORKLOAD_1, WORKLOAD_2, WORKLOAD_3

# EVOLVE-BLOCK-START

import time

def get_best_schedule(workload, num_seqs):
    """
    Conflict-DAG-layered construction with local-search polish and restarts.

    Approach: build a conflict graph between transactions (write-read,
    read-write, or write-write on the same key; pairwise simulator-probe
    fallback if txn ops are not exposed), compute longest-path depth layers
    (transactions in the same layer are mutually conflict-free, so their
    relative order is exactly where prefix-greedy beam search wastes
    lookahead). Construct the permutation layer by layer: within each layer a
    small beam over prefix cost (true `get_opt_seq_cost`, memoized) explores
    the free orderings; cross-layer remainder is completed greedily by prefix
    cost. The seed is polished by a first-improvement descent with relocation,
    pairwise-swap, and 2-opt moves accepted only on strict improvement, then
    improved via double-bridge perturbation restarts. Hard per-workload
    deadline (~100s), tuple-key cost cache, and identity fallback guarantee
    validity and keep all three workloads inside 360s.
    """
    n = workload.num_txns
    if n == 0:
        return 0, []
    deadline = time.time() + 100.0
    B, K = 12, 4
    cache = {}

    def cost(seq):
        key = tuple(seq)
        c = cache.get(key)
        if c is None:
            c = workload.get_opt_seq_cost(list(seq))
            cache[key] = c
        return c

    # Fallback: identity permutation (always valid).
    best_seq = list(range(n))
    best_cost = cost(best_seq)

    # --- Conflict-DAG layering construction ---
    # Build dependencies: deps[i] = set of txns that must precede i.
    ops = None
    for attr in ('txns', 'transactions', 'workload', 'data', 'raw', 'txn_map'):
        v = getattr(workload, attr, None)
        if isinstance(v, dict) and v:
            ops = v
            break
    deps = [set() for _ in range(n)]
    if ops is not None:
        parsed = []
        ok = True
        for k in range(n):
            key = 'txn%d' % k
            if key in ops:
                raw = ops[key]
                toks = raw.split() if isinstance(raw, str) else [str(x) for x in raw]
                pl = []
                for t in toks:
                    if '-' in t:
                        op, item = t[0], t.split('-', 1)[1]
                    else:
                        op, item = t[0], t[1:]
                    pl.append((op, item))
                parsed.append(pl)
            else:
                ok = False
                break
        if ok:
            for i in range(n):
                wi = {item for op, item in parsed[i] if op == 'w'}
                ri = {item for op, item in parsed[i] if op == 'r'}
                for j in range(i):
                    wj = {item for op, item in parsed[j] if op == 'w'}
                    rj = {item for op, item in parsed[j] if op == 'r'}
                    if (wi & rj) or (wj & ri) or (wi & wj):
                        deps[i].add(j)
    else:
        # Fallback: pairwise simulator probes reveal ordering-sensitive pairs.
        for i in range(n):
            for j in range(i + 1, n):
                try:
                    a = cost([i, j])
                    b = cost([j, i])
                except Exception:
                    continue
                if a < b:
                    deps[j].add(i)
                elif b < a:
                    deps[i].add(j)

    # Longest-path depth layering over the dependency DAG.
    depth = [0] * n
    changed = True
    guard = 0
    while changed and guard < n + 5:
        changed = False
        guard += 1
        for i in range(n):
            if deps[i]:
                d = max(depth[j] + 1 for j in deps[i])
                if d != depth[i]:
                    depth[i] = d
                    changed = True
    layers = {}
    for i in range(n):
        layers.setdefault(depth[i], []).append(i)

    # Construct layer by layer; within each layer, small beam on prefix cost.
    beam2 = [()]
    for d in sorted(layers):
        layer = layers[d]
        for _ in layer:
            expanded = []
            for s in beam2:
                placed = set(s)
                for t in layer:
                    if t in placed:
                        continue
                    expanded.append((cost(list(s + (t,))), s + (t,)))
            if not expanded:
                break
            expanded.sort(key=lambda x: x[0])
            beam2 = [s for _, s in expanded[:4]]
            if time.time() > deadline:
                break

    # Greedily complete each beam candidate over the remaining txns.
    for s in beam2:
        rem = [x for x in range(n) if x not in set(s)]
        while rem:
            scored = sorted((cost(list(s + (t,))), t) for t in rem)
            s = s + (scored[0][1],)
            rem.remove(scored[0][1])
            if time.time() > deadline:
                s = s + tuple(rem)
                rem = []
        c = cost(list(s))
        if c < best_cost:
            best_cost, best_seq = c, list(s)

    def descend(seq, cur_cost):
        """First-improvement descent: relocations, swaps, 2-opt reversals."""
        improved = True
        while improved and time.time() < deadline:
            improved = False
            # Relocation moves.
            for i in range(n):
                for j in range(n):
                    if i == j:
                        continue
                    cand = seq[:]
                    v = cand.pop(i)
                    cand.insert(j, v)
                    c = cost(cand)
                    if c < cur_cost:
                        seq, cur_cost = cand, c
                        improved = True
                        break
                    if time.time() > deadline:
                        break
                if improved or time.time() > deadline:
                    break
            if time.time() > deadline:
                break
            # Pairwise swaps.
            for i in range(n - 1):
                for j in range(i + 1, n):
                    cand = seq[:]
                    cand[i], cand[j] = cand[j], cand[i]
                    c = cost(cand)
                    if c < cur_cost:
                        seq, cur_cost = cand, c
                        improved = True
                        break
                    if time.time() > deadline:
                        break
                if improved or time.time() > deadline:
                    break
            if time.time() > deadline:
                break
            # 2-opt segment reversals.
            for i in range(n - 1):
                for j in range(i + 2, n):
                    cand = seq[:]
                    cand[i:j + 1] = cand[i:j + 1][::-1]
                    c = cost(cand)
                    if c < cur_cost:
                        seq, cur_cost = cand, c
                        improved = True
                        break
                    if time.time() > deadline:
                        break
                if improved or time.time() > deadline:
                    break
        return seq, cur_cost

    best_seq, best_cost = descend(best_seq, best_cost)

    # Restart loop: double-bridge perturbation of the incumbent, re-descend.
    while time.time() < deadline:
        seq = best_seq[:]
        if n >= 4:
            a, b, c2 = sorted(random.sample(range(1, n), 3))
            seq = (seq[:a] + seq[b:c2] + seq[a:b] + seq[c2:])
        else:
            i = random.randrange(n - 1)
            j = random.randrange(i + 1, n)
            seq[i:j + 1] = seq[i:j + 1][::-1]
        seq, c = descend(seq, cost(seq))
        if c < best_cost:
            best_cost, best_seq = c, seq[:]

    assert len(set(best_seq)) == n
    return best_cost, best_seq

# EVOLVE-BLOCK-END

def get_random_costs():
    workload_size = 100
    workload = Workload(WORKLOAD_1)

    makespan1, schedule1 = get_best_schedule(workload, 10)
    cost1 = workload.get_opt_seq_cost(schedule1)

    workload2 = Workload(WORKLOAD_2)
    makespan2, schedule2 = get_best_schedule(workload2, 10)
    cost2 = workload2.get_opt_seq_cost(schedule2)

    workload3 = Workload(WORKLOAD_3)
    makespan3, schedule3 = get_best_schedule(workload3, 10)
    cost3 = workload3.get_opt_seq_cost(schedule3)
    print(cost1, cost2, cost3)
    return cost1 + cost2 + cost3, [schedule1, schedule2, schedule3]


if __name__ == "__main__":
    makespan, schedule = get_random_costs()
    print(f"Makespan: {makespan}")
